pub const SecondCodePoint = struct { code_point: u32, entity: []const u8 };

// the entity for a code point. an ambiguous one also names entities for the
// code point followed by another, and its entity is the one to use otherwise
pub const CodePointEntity = struct {
    code_point: u32,
    entity: ?[]const u8,
    ambiguous: bool = false,
    seconds: []const SecondCodePoint = &.{},
};

